        private void Stores_Load(object sender, EventArgs e)
        {
            search_inp.Focus();
        }

        public void Refresh_Grid_Data()
        {
            search_inp.Text = null;
            this.Enabled = false;
            sqlDataSource2.RebuildResultSchema();
            sqlDataSource2.Fill();
            stores_list.Update();
            this.Enabled = true;
        }

        private void refresh_btn_Click(object sender, EventArgs e)
        {
            Refresh_Grid_Data();
            search_inp.Focus();
        }

        private void search_inp_EditValueChanged(object sender, EventArgs e)
        {
            gridView1.ApplyFindFilter(search_inp.Text);
        }

        private void list_Click(object sender, EventArgs e)
        {

        }

        private void stores_list_DoubleClick(object sender, EventArgs e)
        {
            
        }

        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                Store store = new Store();
                store.Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns["Code"]));
                store.Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Name"]));
                store.Company_Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Company Name"]));
                store.Area_Code = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Area Code"]));
                store.Phone = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Phone"]));
                store.Address = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Address"]));
                store.Description = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Description"]));
                Edit_Store edit_store = new Edit_Store(store);
                edit_store.stores = this;
                edit_store.Do_Refresh = true;
                edit_store.Show(this);
            }
        }

        public void Controls_List(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.F1 || e.KeyCode == Keys.Down && search_inp.ContainsFocus)
            {
                gridView1.Focus();
            }
            if ((e.KeyCode == Keys.F2 || e.KeyCode == Keys.Enter) && stores_list.ContainsFocus == true)
            {
                if (gridView1.DataRowCount > 0)
                {
                    Store store = new Store();
                    store.Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns["Code"]));
                    store.Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Name"]));
                    store.Company_Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Company Name"]));
                    store.Area_Code = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Area Code"]));
                    store.Phone = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Phone"]));
                    store.Address = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Address"]));
                    store.Description = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns["Description"]));
                    Edit_Store edit_store = new Edit_Store(store);
                    edit_store.stores = this;
                    edit_store.Do_Refresh = true;
                    edit_store.Show(this);
                }
            }
            if (e.KeyCode == Keys.F3 || (e.Control && e.KeyCode == Keys.F))
            {
                search_inp.Focus();
            }
            if (e.KeyCode == Keys.F6 || (e.Control && e.KeyCode == Keys.N))
            {
                search_inp.Focus();
                New_Store store = new New_Store();
                store.stores = this;
                store.Do_Refresh = true;
                store.ShowDialog(this);
            }
            if (e.KeyCode == Keys.F5 || (e.Control && e.KeyCode == Keys.R))
            {
                Refresh_Grid_Data();
                search_inp.Focus();
            }

        }

        private void search_inp_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }

        private void stores_list_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }
    }
}
